  {const b=$("#acct-btn");if(b)b.innerHTML=acctLabel()}$("#mob-nb-btn").setAttribute("aria-label",T("Notebook","Блокнот"));{const m=$("#mob-acct");if(m){m.textContent=cuser?(cuser.email||"?")[0].toUpperCase():T("Sign in","Войти");m.setAttribute("aria-label",cuser?T("Sign out","Выйти"):T("Sign in","Войти"))}};
  LANGS.forEach(l=>{const b=$("#lang-"+l);if(b)b.setAttribute("aria-pressed",lang===l)});{const b=$("#mob-lang");if(b){b.textContent=lang.toUpperCase();b.setAttribute("aria-label",T("Language","Язык"))}}
  document.documentElement.lang=lang;
