const WHY=[["care",T("Careless slip","Невнимательность")],["rule",T("Didn't know the rule","Не знал правило")],["read",T("Misread the text","Не понял текст")]];
function reasonHTML(){const m=S.m[cur().id]||{};return `<div role="group" aria-label="${T("Why was it missed?","Почему ошибка?")}"><p><b>${T("Why was it missed?","Почему ошибка?")}</b></p><div class="cluster">${WHY.map(([k,l])=>`<button class="btn btn-sm ${m.why===k?"btn-primary":"btn-secondary"}" aria-pressed="${m.why===k}" onclick="App.why('${k}')">${l}</button>`).join("")}</div></div>`}
function reasonRec(){const c={};Object.keys(S.m).forEach(id=>{const m=S.m[id],q=qid(+id);if(q&&m.why){const o=c[q.skill]=c[q.skill]||{care:0,rule:0,read:0,u:q.unitId};o[m.why]++}});
 for(const k in c){const o=c[k];
  if(o.rule>=2)return{title:T(`Learn the rule: ${k}`,`Выучите правило: ${k}`),why:T(`You marked "didn't know the rule" on ${o.rule} questions here. Read the lesson, then try 3 questions.`,`Вы отметили «не знал правило» в ${o.rule} вопросах. Прочитайте урок и решите 3 вопроса.`),cta:T("Open the lesson","Открыть урок"),act:`App.learn('${o.u}')`};
  if(o.read+o.care>=2)return{title:T(`Slow down on: ${k}`,`Не торопитесь: ${k}`),why:T(`You marked ${o.read+o.care} misses here as careless or misread. Practise 3 questions and underline the key words before answering.`,`Вы отметили ${o.read+o.care} ошибок как невнимательность или непонимание текста. Решите 3 вопроса и подчёркивайте ключевые слова.`),cta:T("Try 3 questions","Решить 3 вопроса"),act:`App.prac({un:'${o.u}',n:3,src:'any'})`}}
 return null}
let X=null,xt=null;
