function examStart(sec,unit,sect){const p=sect?sectPick(sect):shuf(Q.filter(q=>unit?q.unitId===unit:(sec?q.section===sec:q.section!=="EN"))).slice(0,10);if(p.length<3){view="practice";return practice(T("Not enough questions for a practice test.","Недостаточно вопросов для теста."))}
 const seconds=(unit||sect)?0:((S.study||DEFAULT_STUDY).practiceSeconds??75),shuffle=(S.study||DEFAULT_STUDY).shuffleAnswers===true;X={list:p.map(q=>q.id),ans:{},mark:{},opts:Object.fromEntries(p.filter(q=>q.type!=="spr").map(q=>[q.id,shuffle?shuf(qv(q,"o").map((_,i)=>i)):qv(q,"o").map((_,i)=>i)])),i:0,end:seconds?now()+p.length*seconds*1000:Infinity,unit:unit||null,sect:sect||null,done:false};view="exam";clearInterval(xt);if(seconds)xt=setInterval(()=>{if(!X||X.done)return clearInterval(xt);const l=X.end-now(),e=$("#xtimer");if(e)e.textContent=fmtT(l);if(l<=0)examSubmit(true)},1000);drawX()}
function drawX(){const id=X.list[X.i],q=qid(id),n=X.list.length,a=X.ans[id];
 show(`<header class="page-header"><div><span class="eyebrow">${X.sect?T("Section Test","Тест раздела")+" · "+esc(L(sectCo(X.sect).title)):X.unit?T("Unit Test","Тест модуля")+" · "+esc(L(unitOf(X.unit).title)):T("Practice test · not an official SAT","Тренировочный тест · не официальный SAT")}</span><h1>${T("Question","Вопрос")} ${X.i+1} / ${n}</h1></div>${X.unit||X.sect||!Number.isFinite(X.end)?"":`<div class="badge badge-accent" role="timer" style="font-size:1.1rem">⏱ <span id="xtimer">${fmtT(X.end-now())}</span></div>`}</header>
 <div class="cluster" style="margin:.4rem 0" role="group" aria-label="${T("Questions","Вопросы")}">${X.list.map((x,k)=>`<button class="btn btn-sm ${k===X.i?"btn-primary":"btn-secondary"}" onclick="App.xgo(${k})" aria-label="${T("Question","Вопрос")} ${k+1}${X.ans[x]!=null&&X.ans[x]!==""?", "+T("answered","есть ответ"):""}${X.mark[x]?", "+T("marked","отмечен"):""}">${k+1}${X.mark[x]?" ⚑":X.ans[x]!=null&&X.ans[x]!==""?" •":""}</button>`).join("")}</div>
 ${qv(q,"p")?`<div class="stimulus-box" style="white-space:pre-line">${mx(qv(q,"p"))}</div>`:""}<p class="question-prompt" style="margin-top:1rem">${mx(qv(q,"q"))}</p>
 ${q.type==="spr"?`<div class="field"><label for="xs">${T("Your answer","Ваш ответ")}</label><input class="input" id="xs" inputmode="decimal" autocomplete="off" maxlength="12" value="${esc(a==null?"":a)}" oninput="App.xset(this.value)" style="max-width:12rem"></div>`:`<div class="choice-list stack" style="gap:.6rem">${(X.opts[id]||qv(q,"o").map((_,i)=>i)).map((oi,pos)=>{const o=qv(q,"o")[oi];return `<button class="choice-btn ${a===oi?"selected":""}" aria-pressed="${a===oi}" onclick="App.xset(${pos})"><span class="choice-key">${"ABCD"[pos]}</span><span>${mx(o)}</span></button>`}).join("")}</div>`}
 <div class="cluster" style="margin-top:1rem"><button class="btn btn-secondary btn-sm" onclick="App.xmark()">${X.mark[id]?T("Unmark","Снять отметку"):T("Mark for review","Отметить")}</button><button class="btn btn-secondary btn-sm" ${X.i?"":"disabled"} onclick="App.xgo(${X.i-1})">${T("Back","Назад")}</button><button class="btn btn-secondary btn-sm" ${X.i<n-1?"":"disabled"} onclick="App.xgo(${X.i+1})">${T("Next","Дальше")}</button><button class="btn btn-primary" onclick="App.xfin()">${T("Finish test","Завершить тест")}</button></div>`)}
function examSubmit(timeUp){if(!X||X.done)return;X.done=true;clearInterval(xt);
 const rows=X.list.map(id=>{const q=qid(id),s=X.ans[id],has=!(s==null||s==="");const ok=has&&(q.type==="spr"?sprOk(q,s):s===q.c);if(has)record(q,q.type==="spr"?String(s):s,ok,"exam");return{q,s,has,ok}});
 const c=rows.filter(r=>r.ok).length;view="examr";if(X.sect)return sectResult(rows,c);if(X.unit)return unitResult(rows,c,timeUp);
 show(head(T("Practice test results","Итоги тренировочного теста"),T(`${c} of ${rows.length} correct`,`Верно: ${c} из ${rows.length}`)+(timeUp?" · "+T("time ran out","время вышло"):""))+`<div class="card card-warn"><p>${T("This is a short informal practice test. It is not an official SAT and does not predict a score. Missed questions are now in your notebook.","Это короткий неформальный тренировочный тест. Он не является официальным SAT и не предсказывает балл. Ошибки добавлены в блокнот.")}</p></div><div class="stack">${rows.map((r,i)=>`<div class="card"><div class="between"><span class="badge">${i+1}. ${esc(r.q.skill)}</span><span class="badge ${r.ok?"badge-ok":"badge-err"}">${r.ok?T("Correct","Верно"):r.has?T("Incorrect","Неверно"):T("Unanswered","Нет ответа")}</span></div><p>${mx(qv(r.q,"q"))}</p><p class="text-muted">${T("Your answer","Ваш ответ")}: ${r.has?ans(r.q,r.s):"—"} · ${T("Correct answer","Правильный ответ")}: ${r.q.type==="spr"?mx(r.q.ans[0]):ans(r.q,r.q.c)}</p><p>${mx(qv(r.q,"e"))}</p><p><b>${T("Takeaway","Вывод")}:</b> ${mx(qv(r.q,"t"))}</p></div>`).join("")}</div><div class="cluster" style="margin-top:1rem"><button class="btn btn-primary" onclick="App.go('notebook')">${T("Open notebook","Открыть блокнот")}</button><button class="btn btn-secondary" onclick="App.go('practice')">${T("Back to practice","К практике")}</button></div>`)}
function go(v){if(X&&!X.done)return ask(T("Leave the test?","Выйти из теста?"),T("Your answers will be lost.","Ответы пропадут."),T("Leave","Выйти"),()=>{clearInterval(xt);X=null;go(v)},"danger");if(X){clearInterval(xt);X=null}view=v;R=null;({home,path,learn:()=>learn(arg),vocab:vocabulary,practice:()=>practice(),review,notebook:()=>notebook(),progress,settings:()=>settings(),diag}[v]||home)()}
