const syncLabel=()=>({saving:T("Saving…","Сохранение…"),on:T("Saved","Сохранено"),offline:T("Offline","Нет сети"),error:T("Sync error","Ошибка синхронизации")})[sync]||"";
function cloudPush(){if(!cuser||!window.CS)return;clearTimeout(ct);if(!navigator.onLine)return setSync("offline");setSync("saving");ct=setTimeout(()=>{const a=S.a.length>2000?S.a.slice(-2000):S.a;window.CS.save(cuser,JSON.stringify(Object.assign({},S,{a})),S.upd).then(raw=>{if(raw){const c=clean(raw);if(c){S=merge(S,c);try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){storeOk=false;banner()}}}setSync("on")},()=>setSync(navigator.onLine?"error":"offline"))},1500)}
function merge(a,b){const k=new Set(),all=[];[...a.a,...b.a].forEach(t=>{const x=t.id+"_"+t.ts;if(!k.has(x)){k.add(x);all.push(t)}});all.sort((p,q)=>p.ts-q.ts);
 const seen=new Set();all.forEach(t=>{t.first=!seen.has(t.id);seen.add(t.id)});
 const last=(s,id)=>Math.max(0,...s.a.filter(t=>t.id===id).map(t=>t.ts)),m={};
 new Set([...Object.keys(a.m),...Object.keys(b.m)]).forEach(id=>{const x=a.m[id],y=b.m[id];m[id]=!x?y:!y?x:(last(a,+id)>=last(b,+id)?x:y)});
 const ut={};new Set([...Object.keys(a.ut||{}),...Object.keys(b.ut||{})]).forEach(k=>{const mp=new Map();[...((a.ut||{})[k]||[]),...((b.ut||{})[k]||[])].forEach(t=>mp.set(t.ts,t));ut[k]=[...mp.values()].sort((p,q)=>p.ts-q.ts)});
  const st={};new Set([...Object.keys(a.st||{}),...Object.keys(b.st||{})]).forEach(k=>{const mp=new Map();[...((a.st||{})[k]||[]),...((b.st||{})[k]||[])].forEach(t=>mp.set(t.ts,t));st[k]=[...mp.values()].sort((p,q)=>p.ts-q.ts)});
 const n=a.upd>=b.upd?a:b;return Object.assign({},n,{ut,st,a:all,m,lc:Object.assign({},a.lc,b.lc),d:Object.assign({},a.d,b.d),prof:n.prof||a.prof||b.prof,upd:Math.max(a.upd,b.upd)})}
function offerGuest(g,u){if(!g||!((g.a&&g.a.length)||Object.keys(g.m||{}).length))return;const sk="cs2_skip:"+u.uid;try{if(localStorage.getItem(sk)===String(g.upd))return;localStorage.setItem(sk,String(g.upd))}catch(e){}
 ask(T("Add progress from this browser?","Добавить прогресс из этого браузера?"),T("This browser has progress saved without an account. Add it to this account? Choose Cancel to keep it separate.","В этом браузере есть прогресс без аккаунта. Добавить его в этот аккаунт? Нажмите «Отмена», чтобы оставить его отдельно."),T("Add it","Добавить"),()=>{S=merge(S,g);try{localStorage.removeItem(GUEST)}catch(e){}save();nav();go(view)})}
