 if(u){const k=GUEST+":"+u.uid;if(KEY===GUEST)guest=S;if(KEY!==k){KEY=k;S=blank();load()}cuser=u}
 else{cuser=null;if(KEY!==GUEST){KEY=GUEST;S=blank();load()}setSync("off");nav();if(["home","path","progress","notebook","review","settings"].includes(view))go(view);return}
