const acctLabel=()=>cuser?`<span class="av" aria-hidden="true">${esc(((cuser.displayName||cuser.email||"?").trim()[0]||"?").toUpperCase())}</span><span class="al">${T("Sign out","Выйти")}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/></svg>`:`<span class="al">${T("Sign in","Войти")}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4M10 17l5-5-5-5M15 12H3"/></svg>`;
const syncText=()=>cuser?T(`Signed in as ${esc(cuser.email)}. Your progress saves automatically to your ClearStep account and follows you across devices. Only you can read it. A copy also stays in this browser.`+(sync==="error"?" The last cloud save failed; your local copy is safe.":"")+(sync==="offline"?" You are offline; changes will sync when the connection returns.":""),`Вы вошли как ${esc(cuser.email)}. Прогресс автоматически сохраняется в вашем аккаунте ClearStep и доступен на разных устройствах. Читать его можете только вы. Копия также остаётся в этом браузере.`+(sync==="error"?" Последнее облачное сохранение не удалось; локальная копия цела.":"")+(sync==="offline"?" Вы без сети; изменения синхронизируются, когда связь вернётся.":"")):T("Not signed in. Progress is stored only in this browser, does not sync between devices and can be lost if you clear browser data. Sign in to keep it in your account.","Вы не вошли. Прогресс хранится только в этом браузере, не синхронизируется между устройствами и может пропасть при очистке данных. Войдите, чтобы хранить его в аккаунте.");


