let authMode="in",authEmail="",authBusy=false;
const friendly=e=>{const m=String((e&&e.message)||e||"");
 if(/invalid login/i.test(m))return T("Wrong email or password.","Неверная почта или пароль.");
 if(/not confirmed/i.test(m))return T("Please confirm your email first. Check your inbox.","Сначала подтвердите почту. Проверьте входящие.");
 if(/rate limit|too many|security purposes/i.test(m))return T("Too many attempts. Please wait a minute and try again.","Слишком много попыток. Подождите минуту и повторите.");
 if(/password.*(short|least|weak)|at least/i.test(m))return T("Use a password of at least 8 characters.","Пароль должен быть не короче 8 символов.");
 if(/fetch|network|failed to/i.test(m))return T("No connection. Check your internet and try again.","Нет соединения. Проверьте интернет и повторите.");
 return m||T("Something went wrong. Please try again.","Что-то пошло не так. Повторите попытку.")};
function authOpen(){
 if(cuser)return modal(`<h2 id="modal-title">${T("Your account","Ваш аккаунт")}</h2><p class="text-muted"><b>${esc(cuser.displayName||T("ClearStep learner","Ученик ClearStep"))}</b><br>${esc(cuser.email)}</p><div class="stack"><button class="btn btn-secondary" onclick="App.closeModal();App.go('settings')">${T("My Profile & Settings","Мой профиль и настройки")}</button><button class="btn btn-secondary" onclick="App.closeModal();App.go('path')">${T("My Learning","Обучение")}</button><button class="btn btn-secondary" onclick="App.closeModal();App.go('progress')">${T("Progress","Прогресс")}</button><button class="btn btn-secondary" onclick="App.closeModal();App.openFeedback()">${T("Help & Feedback","Помощь и отзыв")}</button><button class="btn btn-danger" onclick="App.signOutAsk()">${T("Sign out","Выйти")}</button></div>`);
 if(!window.CS||!window.CS.configured)return ask(T("Accounts are not set up yet","Аккаунты ещё не настроены"),T("Sign-in will work after the site owner connects Supabase (see SUPABASE_SETUP.md). Your progress is still saved in this browser.","Вход заработает после подключения Supabase владельцем сайта (см. SUPABASE_SETUP.md). Прогресс пока сохраняется в этом браузере."),"OK",null,"warn");
 authMode="in";authDraw()}
function authDraw(msg,bad){const up=authMode==="up";
 modal(`<h2 id="modal-title">${up?T("Create account","Создать аккаунт"):T("Sign in","Войти")}</h2>
<p class="text-muted">${T("Your progress saves to your account and follows you across devices.","Прогресс сохраняется в аккаунте и доступен на разных устройствах.")}</p>
<div id="auth-msg" class="card ${bad?"card-warn":"card-highlight"}" role="status" ${msg?"":"hidden"}>${msg||""}</div>
<div class="stack"><button type="button" class="btn btn-secondary" onclick="App.authDo('google')">${T("Continue with Google","Продолжить с Google")}</button>
<form class="stack" onsubmit="App.authDo('submit',event)" novalidate>
<div class="field"><label for="au-e">${T("Email","Почта")}</label><input class="input" id="au-e" type="email" autocomplete="email" value="${esc(authEmail)}" required></div>
<div class="field"><label for="au-p">${T("Password","Пароль")}</label><input class="input" id="au-p" type="password" autocomplete="${up?"new-password":"current-password"}" minlength="8"></div>
<button class="btn btn-primary" type="submit">${up?T("Create account","Создать аккаунт"):T("Sign in","Войти")}</button></form>
<button type="button" class="btn btn-secondary" onclick="App.authDo('link')">${T("Email me a sign-in link","Прислать ссылку для входа")}</button>
<div class="cluster">${up?"":`<button type="button" class="btn btn-sm btn-secondary" onclick="App.authDo('reset')">${T("Forgot password?","Забыли пароль?")}</button>`}<button type="button" class="btn btn-sm btn-secondary" onclick="App.authSwitch()">${up?T("I already have an account","У меня уже есть аккаунт"):T("Create an account","Создать аккаунт")}</button><button type="button" class="btn btn-sm btn-secondary" onclick="App.closeModal()">${T("Close","Закрыть")}</button></div></div>`)}
function authSwitch(){authEmail=($("#au-e")||{}).value||authEmail;authMode=authMode==="up"?"in":"up";authDraw()}
async function authDo(kind,ev){if(ev)ev.preventDefault();if(authBusy)return;
 const em=(($("#au-e")||{}).value||"").trim(),pw=($("#au-p")||{}).value||"";authEmail=em;
 if(kind!=="google"&&!/^\S+@\S+\.\S+$/.test(em))return authDraw(T("Enter a valid email address.","Введите корректный адрес почты."),1);
 if(kind==="submit"&&pw.length<8)return authDraw(T("Use a password of at least 8 characters.","Пароль должен быть не короче 8 символов."),1);
 authBusy=true;document.querySelectorAll("#modal-body button").forEach(b=>b.disabled=true);
 try{
  if(kind==="google"){await window.CS.signInGoogle();return}
  if(kind==="link"){await window.CS.magicLink(em);authBusy=false;return authDraw(T(`We sent a sign-in link to ${esc(em)}. Open it on this device.`,`Мы отправили ссылку для входа на ${esc(em)}. Откройте её на этом устройстве.`))}
  if(kind==="reset"){await window.CS.resetPassword(em);authBusy=false;return authDraw(T(`If an account exists for ${esc(em)}, a reset link is on its way.`,`Если аккаунт для ${esc(em)} существует, ссылка для сброса уже отправлена.`))}
  if(authMode==="up"){const r=await window.CS.signUp(em,pw);authBusy=false;
   if(r.exists){authMode="in";return authDraw(T("An account with this email already exists. Sign in instead.","Аккаунт с этой почтой уже есть. Войдите."),1)}
   if(r.needsConfirm){authMode="in";return authDraw(T(`Check ${esc(em)} and confirm your address, then sign in.`,`Проверьте ${esc(em)} и подтвердите адрес, затем войдите.`))}
   return closeModal()}
  await window.CS.signIn(em,pw);authBusy=false;closeModal()
 }catch(e){authBusy=false;authDraw(friendly(e),1)}}
function authPassword(rec){
 modal(`<h2 id="modal-title">${rec?T("Set a new password","Задайте новый пароль"):T("Change password","Сменить пароль")}</h2><div id="auth-msg" class="card card-warn" role="alert" hidden></div><form class="stack" onsubmit="App.authPwSave(event)"><div class="field"><label for="pw1">${T("New password (8+ characters)","Новый пароль (8+ символов)")}</label><input class="input" id="pw1" type="password" autocomplete="new-password" minlength="8"></div><div class="field"><label for="pw2">${T("Repeat password","Повторите пароль")}</label><input class="input" id="pw2" type="password" autocomplete="new-password" minlength="8"></div><div class="cluster"><button class="btn btn-primary" type="submit">${T("Save password","Сохранить пароль")}</button><button type="button" class="btn btn-secondary" onclick="App.closeModal()">${T("Cancel","Отмена")}</button></div></form>`)}
async function authPwSave(ev){ev.preventDefault();if(authBusy)return;const a=$("#pw1").value,b=$("#pw2").value,m=$("#auth-msg");
 const err=x=>{m.hidden=false;m.textContent=x};
 if(a.length<8)return err(T("Use a password of at least 8 characters.","Пароль должен быть не короче 8 символов."));
 if(a!==b)return err(T("The passwords do not match.","Пароли не совпадают."));
 authBusy=true;try{await window.CS.updatePassword(a);authBusy=false;closeModal();ask(T("Password updated","Пароль обновлён"),T("Use the new password next time you sign in.","Используйте новый пароль при следующем входе."),"OK")}catch(e){authBusy=false;err(friendly(e))}}
function delAsk(){ask(T("Delete your account?","Удалить аккаунт?"),T("This permanently deletes your account and your cloud progress. This cannot be undone.","Аккаунт и облачный прогресс будут удалены навсегда. Это нельзя отменить."),T("Delete account","Удалить аккаунт"),()=>{const u=cuser;window.CS.deleteAccount().then(()=>{try{localStorage.removeItem(GUEST+":"+u.uid)}catch(e){}ask(T("Account deleted","Аккаунт удалён"),T("Your account and cloud progress were removed.","Аккаунт и облачный прогресс удалены."),"OK")}).catch(e=>ask(T("Could not delete the account","Не удалось удалить аккаунт"),friendly(e),"OK",null,"warn"))},"danger")}
function profileSave(ev){ev.preventDefault();const name=$("#profile-name").value.trim();if(!name||name.length>80)return settings(T("Enter a name up to 80 characters.","Введите имя длиной до 80 символов."));window.CS.updateProfile(name).then(()=>{cuser=window.CS.user;nav();settings(T("Profile name updated.","Имя профиля обновлено."))}).catch(e=>settings(esc(friendly(e))))}
function emailSave(ev){ev.preventDefault();const email=$("#profile-email").value.trim();if(!/^[\S]+@[\S]+\.[\S]+$/.test(email))return settings(T("Enter a valid email address.","Введите корректный адрес почты."));if(email.toLowerCase()===String(cuser.email).toLowerCase())return settings(T("That is already your current email.","Это уже текущий адрес почты."));window.CS.updateEmail(email).then(()=>settings(T("The email change request was submitted. Follow any confirmation instructions Supabase sends; the account email will update when the change is applied.","Запрос на смену почты отправлен. Выполните инструкции Supabase, если потребуется подтверждение; адрес аккаунта обновится после применения изменения."))).catch(e=>settings(esc(friendly(e))))}
const acctCard=()=>cuser?`<div class="card" style="margin-top:1.2rem"><h2>${T("Account & security","Аккаунт и безопасность")}</h2><p class="text-muted">${T("Sign-in method","Способ входа")}: ${esc(cuser.provider||"email")}</p><p class="text-muted">${T("Email status","Статус почты")}: ${cuser.emailConfirmed?T("Confirmed","Подтверждена"):T("Not confirmed","Не подтверждена")}</p><form class="stack" onsubmit="App.profileSave(event)"><div class="field"><label for="profile-name">${T("Profile name","Имя профиля")}</label><input class="input" id="profile-name" maxlength="80" value="${esc(cuser.displayName||"")}" autocomplete="name"></div><button class="btn btn-secondary" type="submit">${T("Save profile name","Сохранить имя")}</button></form><form class="stack" style="margin-top:1rem" onsubmit="App.emailSave(event)"><div class="field"><label for="profile-email">${T("Change email","Изменить адрес почты")}</label><input class="input" id="profile-email" type="email" autocomplete="email" placeholder="${esc(cuser.email)}" required></div><button class="btn btn-secondary" type="submit">${T("Send confirmation","Отправить подтверждение")}</button></form><div class="cluster" style="margin-top:1rem"><button class="btn btn-secondary" onclick="App.authPassword()">${T("Change password","Сменить пароль")}</button><button class="btn btn-danger" onclick="App.delAsk()">${T("Delete account","Удалить аккаунт")}</button></div></div>`:"";
